<?php
namespace App\Http\Controllers;
use App\Models\{BiometricConsent,BiometricDeletionRequest,EventFaceIndexRun,FaceMatchResult,FaceSearchSubject,Group,MediaAsset,MediaExport,Photo,UploadBatch};use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;use Inertia\Inertia;
use App\Support\UploadStatusPresenter;
class LensPicUiController extends Controller
{
    public function __construct(private \App\Services\Media\GroupCoverPresenter $coverPresenter) {}
    public function dashboard(Request$r){if($r->user()->isSuperAdmin())return redirect()->route('super-admin.dashboard');$owner=app(\App\Services\Team\TeamAuthorization::class)->ownerFor($r->user())??$r->user();$owned=$owner->createdGroups()->withCount(['photos','members'])->latest()->limit(6)->get();return Inertia::render('Dashboard',['stats'=>['groups'=>$owner->createdGroups()->count(),'photos'=>Photo::whereIn('group_id',$owner->createdGroups()->select('id'))->count(),'participants'=>$owned->sum('members_count'),'processing'=>MediaAsset::whereIn('group_id',$owned->pluck('id'))->whereIn('state',['queued','processing'])->count()],'groups'=>$owned,'recent'=>[]]);}
    public function analytics(Request$r){$this->authorize('create',Group::class);$owner=app(\App\Services\Team\TeamAuthorization::class)->ownerFor($r->user())??$r->user();$groups=$owner->createdGroups()->withCount(['photos','members'])->latest()->get();return Inertia::render('Analytics',['summary'=>['groups'=>$groups->count(),'photos'=>$groups->sum('photos_count'),'participants'=>$groups->sum('members_count'),'storage_bytes'=>(int)$owner->storage_used],'groups'=>$groups->map(fn($g)=>['id'=>$g->id,'name'=>$g->name,'photos_count'=>$g->photos_count,'members_count'=>$g->members_count,'updated_at'=>$g->updated_at])]);}
    public function notifications(Request$r){$available=\Illuminate\Support\Facades\Schema::hasTable('notifications');$items=$available?$r->user()->notifications()->latest()->limit(50)->get()->map(fn($n)=>['id'=>$n->id,'type'=>class_basename($n->type),'data'=>$n->data,'read_at'=>$n->read_at,'created_at'=>$n->created_at]):collect();return Inertia::render('Notifications',['notifications'=>$items,'backendAvailable'=>$available]);}
    public function events(Request$r){$relations=['coverMediaAsset.variants','pendingCoverMediaAsset.variants','creator:id,name'];$counts=['photos','members','folders'];$owner=app(\App\Services\Team\TeamAuthorization::class)->ownerFor($r->user())??$r->user();$groups=$owner->createdGroups()->with($relations)->withCount($counts)->latest()->get()->merge($r->user()->groups()->with($relations)->withCount($counts)->latest()->get())->unique('id')->values()->map(fn($g)=>['id'=>$g->id,'name'=>$g->name,'event_type'=>$g->event_type,'event_date'=>$g->event_date,'privacy'=>$g->privacy,'cover'=>$this->coverPresenter->present($g,'cover_grid'),'owner_name'=>$g->creator?->name,'is_active'=>$g->is_active,'photos_count'=>$g->photos_count,'members_count'=>$g->members_count,'folders_count'=>$g->folders_count,'created_at'=>$g->created_at,'updated_at'=>$g->updated_at]);return Inertia::render('Groups/Index',['groups'=>$groups]);}
    public function create(Request$r){$this->authorize('create',Group::class);return Inertia::render('Groups/Create');}
    public function show(Request$r,Group$group)
    {
        Gate::authorize('view',$group);
        $group->load(['creator.businessBranding','coverMediaAsset.variants','pendingCoverMediaAsset.variants']);
        $admin=Gate::forUser($r->user())->allows('update',$group);
        if($admin)foreach([\App\Models\GroupAccessInvite::PARTIAL,\App\Models\GroupAccessInvite::FULL]as$type)\App\Models\GroupAccessInvite::firstOrCreate(['group_id'=>$group->id,'access_type'=>$type],['access_code'=>\App\Models\GroupAccessInvite::generateCode(),'invitation_token'=>\Illuminate\Support\Str::random(48),'created_by'=>$r->user()->id]);
        $tab=(string)$r->query('tab','all');
        $folders=$group->folders()->withCount('photos')->get();
        $validTabs=collect(['all','highlights'])->when($group->favourites_enabled,fn($tabs)=>$tabs->push('favorites'))->merge($folders->map(fn($f)=>'folder-'.$f->id));
        if(!$validTabs->contains($tab))$tab='all';

        $query=$group->photos()->whereHas('mediaAsset',fn($q)=>$q->where('state','completed'))->withCount('likes')->with(['mediaAsset','mediaAsset.variants','likes'=>fn($q)=>$q->where('users.id',$r->user()->id)])->latest('photos.id');
        if(!$group->hasFullAccess($r->user())){
            $matched=(array)$r->session()->get('face_matches.'.$group->id,[]);
            $query->where(fn($q)=>$q->whereHas('folder',fn($folder)=>$folder->where('highlighted',true))->orWhereIn('photos.id',$matched));
        }
        if($tab==='highlights')$query->whereHas('folder',fn($q)=>$q->where('highlighted',true));
        elseif($tab==='favorites')$query->whereHas('likes',fn($q)=>$q->where('users.id',$r->user()->id));
        elseif(str_starts_with($tab,'folder-'))$query->where('folder_id',(int)substr($tab,7));

        $photos=$query->paginate(48)->withQueryString()->through(function($p)use($r){
            abort_unless(Gate::forUser($r->user())->allows('view',$p),403);
            $asset=$p->mediaAsset;
            $width=(int)($asset?->width?:$p->width?:4);
            $height=(int)($asset?->height?:$p->height?:3);
            return ['id'=>$p->id,'original_filename'=>$p->original_filename,'url'=>route('media.show',[$asset->uuid,'grid']),'thumbnail_url'=>route('media.show',[$asset->uuid,'thumbnail']),'viewer_url'=>route('photos.show',[$p->group_id,$p->id]),'download_url'=>Gate::forUser($r->user())->allows('download',$p)?route('photos.download',[$p->group_id,$p->id]):null,'width'=>$width,'height'=>$height,'liked'=>$p->likes->isNotEmpty(),'favourites_count'=>$p->likes_count];
        });

        return Inertia::render('Groups/Show',[
            'group'=>[...$group->only('id','name','event_date','location','privacy','is_active','downloads_enabled','favourites_enabled','face_recognition_enabled'),'cover'=>$this->coverPresenter->present($group,'cover_large'),'owner_name'=>$group->creator?->name,'share_url'=>$admin?null:$group->share_url,'share_endpoint'=>$admin?route('groups.share-link',$group):null,'can_share_group'=>$admin||app(\App\Services\GroupAccessResolver::class)->role($group,null)==='anonymous_full','photos_count'=>$group->photos()->count()],
            'canManage'=>$admin,
            'canUpload'=>Gate::forUser($r->user())->allows('upload',$group),
            'activeTab'=>$tab,
            'tabs'=>collect([['key'=>'all','label'=>'All Photos','count'=>$group->photos()->count()],['key'=>'highlights','label'=>'Highlights','count'=>$group->photos()->whereHas('folder',fn($q)=>$q->where('highlighted',true))->count()]])->merge($folders->map(fn($f)=>['key'=>'folder-'.$f->id,'label'=>$f->name,'count'=>$f->photos_count]))->when($group->favourites_enabled,fn($tabs)=>$tabs->push(['key'=>'favorites','label'=>'Favorites','count'=>$group->photos()->whereHas('likes',fn($q)=>$q->where('users.id',$r->user()->id))->count()]))->values(),
            'photos'=>$photos,
            'branding'=>app(\App\Services\Branding\BusinessBrandingPresenter::class)->gallery($group),
            'photoUploadLimits'=>['maxFileMb'=>config('media.photo_upload.max_file_mb'),'maxBatchFiles'=>config('media.photo_upload.max_batch_files'),'concurrency'=>config('media.photo_upload.concurrency')],
        ]);
    }
    public function biometric(Request$r,Group$group){abort_unless($group->isMember($r->user())&&$group->face_recognition_enabled,403);$consent=BiometricConsent::where('group_id',$group->id)->where('user_id',$r->user()->id)->latest()->first();$subject=$consent?->subjects()->latest()->first();$deletion=BiometricDeletionRequest::where('group_id',$group->id)->where('user_id',$r->user()->id)->latest()->first();return Inertia::render('Biometric/ConsentSelfie',['event'=>$group->only('id','name'),'purpose'=>config('face.consent_purpose'),'consentVersion'=>config('face.consent_version'),'minorEnabled'=>(bool)config('face.minor_processing_enabled'),'consent'=>$consent?->only('uuid','state','privacy_notice_version','granted_at','withdrawn_at'),'subject'=>$subject?->only('uuid','state','outcome','deletion_state','expires_at'),'deletion'=>$deletion?->only('uuid','state','requested_at','completed_at')]);}
    public function myPhotos(Request$r,FaceSearchSubject$s){abort_unless($s->user_id===$r->user()->id,403);abort_unless($s->consent->state==='granted'&&$s->consent->group->isMember($r->user()),403);$rows=$s->results()->whereIn('review_state',['accepted','confirmed','unreviewed'])->with('asset.photo.group')->get();$authorizedMatchIds=$rows->whereIn('review_state',['accepted','confirmed'])->pluck('asset.photo_id')->filter()->map(fn($id)=>(int)$id)->values()->all();$r->session()->put('face_matches.'.$s->group_id,$authorizedMatchIds);$photos=$rows->filter(function($m)use($r){$p=$m->asset?->photo;return$p&&$m->asset->state==='completed'&&Gate::forUser($r->user())->allows('view',$p);})->map(fn($m)=>['match_id'=>$m->id,'photo_id'=>$m->asset->photo_id,'url'=>route('media.show',[$m->asset->uuid,'thumbnail']),'download_url'=>Gate::forUser($r->user())->allows('download',$m->asset)?route('media.show',[$m->asset->uuid,'original','download'=>1]):null,'similarity'=>(float)$m->similarity,'review_state'=>$m->review_state])->values();return Inertia::render('MyPhotos',['subject'=>$s->only('uuid','state','outcome','deletion_state','expires_at'),'photos'=>$photos,'event'=>$s->consent->group->only('id','name'),'partialError'=>$rows->count()>$photos->count(),'consent'=>$s->consent->only('uuid','state'),'deletion'=>BiometricDeletionRequest::where('group_id',$s->group_id)->where('user_id',$r->user()->id)->latest()->first()?->only('uuid','state')]);}
    public function photo(Request$r,Group$group,Photo$photo)
    {
        abort_unless($photo->group_id===$group->id,404);Gate::authorize('view',$photo);abort_if($photo->mediaAsset&&$photo->mediaAsset->state!=='completed',404);
        $tab=(string)$r->query('tab','all');$folders=$group->folders()->pluck('id')->map(fn($id)=>(int)$id);
        $valid=collect(['all','highlights'])->when($group->favourites_enabled,fn($tabs)=>$tabs->push('favorites'))->merge($folders->map(fn($id)=>'folder-'.$id));if(!$valid->contains($tab))$tab='all';
        $sequence=$group->photos()->where(fn($q)=>$q->whereDoesntHave('mediaAsset')->orWhereHas('mediaAsset',fn($asset)=>$asset->where('state','completed')));
        if(!$group->hasFullAccess($r->user())){$matched=(array)$r->session()->get('face_matches.'.$group->id,[]);$sequence->where(fn($q)=>$q->whereHas('folder',fn($folder)=>$folder->where('highlighted',true))->orWhereIn('photos.id',$matched));}
        if($tab==='highlights')$sequence->whereHas('folder',fn($q)=>$q->where('highlighted',true));elseif($tab==='favorites')$sequence->whereHas('likes',fn($q)=>$q->where('users.id',$r->user()->id));elseif(str_starts_with($tab,'folder-'))$sequence->where('folder_id',(int)substr($tab,7));
        abort_unless((clone$sequence)->whereKey($photo->id)->exists(),404);$query=['tab'=>$tab,'page'=>max(1,(int)$r->query('page',1))];$url=fn(?Photo$p)=>$p?route('photos.show',[$group,$p]+$query):null;
        $previous=(clone$sequence)->where('photos.id','>',$photo->id)->orderBy('photos.id')->first();$next=(clone$sequence)->where('photos.id','<',$photo->id)->orderByDesc('photos.id')->first();$first=(clone$sequence)->orderByDesc('photos.id')->first();
        $photo->load(['mediaAsset','uploader:id,name','folder:id,name'])->loadCount('likes');$asset=$photo->mediaAsset;$canDelete=Gate::forUser($r->user())->allows('delete',$photo);
        $share=null;$canManageInvites=Gate::forUser($r->user())->allows('manageInvitations',$group);if($canManageInvites){$invite=$group->accessInvites()->where('access_type',\App\Models\GroupAccessInvite::FULL)->get()->first(fn($candidate)=>$candidate->isUsable());if($invite)$share=['url'=>$invite->url,'access_code'=>$invite->access_code,'expires_at'=>$invite->expires_at?->toIso8601String(),'endpoint'=>null];else$share=['url'=>null,'access_code'=>null,'expires_at'=>null,'endpoint'=>route('groups.share-link',$group)];}if(!$share&&app(\App\Services\GroupAccessResolver::class)->role($group,null)==='anonymous_full')$share=['url'=>$group->share_url,'access_code'=>null,'expires_at'=>null,'endpoint'=>null];
        return Inertia::render('Photos/Show',['event'=>[...$group->only('id','name','downloads_enabled','favourites_enabled'),'gallery_url'=>route('groups.gallery',$group).'?'.http_build_query($query),'can_share_group'=>(bool)$share,'share'=>$share],'photo'=>['id'=>$photo->id,'url'=>$asset?route('media.show',[$asset->uuid,'viewer']):$photo->url,'zoom_url'=>$asset?route('media.show',[$asset->uuid,'optimized']):$photo->url,'download_url'=>Gate::forUser($r->user())->allows('download',$photo)?route('photos.download',[$group,$photo]):null,'caption'=>$photo->caption,'original_filename'=>$photo->original_filename,'uploader'=>$photo->uploader?->name,'folder'=>$photo->folder?->name,'likes_count'=>$photo->likes_count,'liked'=>$photo->isLikedBy($r->user()),'width'=>(int)($asset?->width?:$photo->width),'height'=>(int)($asset?->height?:$photo->height),'mime_type'=>$canDelete?$photo->mime_type:null,'file_size'=>$canDelete?(int)$photo->file_size:null,'created_at'=>$photo->created_at?->toIso8601String(),'can_delete'=>$canDelete],'viewer'=>['tab'=>$tab,'position'=>(clone$sequence)->where('photos.id','>',$photo->id)->count()+1,'total'=>(clone$sequence)->count(),'first_url'=>$url($first),'previous_url'=>$url($previous),'next_url'=>$url($next)]]);
    }
    public function operations(Request$r,Group$group){Gate::authorize('update',$group);$batches=UploadBatch::where('group_id',$group->id)->where('user_id',$r->user()->id)->with('files:id,upload_batch_id,client_filename,state,error,attempts')->latest()->limit(20)->get()->map(function($batch){$batch->refreshCounts();$batch->refresh();return[...$batch->only('uuid','state','total_files','pending_files','processing_files','completed_files','failed_files','cancelled_files','cancelled_at'),'display_status'=>UploadStatusPresenter::label($batch->state),'display_message'=>UploadStatusPresenter::message($batch->state,$batch->completed_files,$batch->total_files,$batch->failed_files),'files'=>$batch->files->map(fn($file)=>[...$file->only('id','client_filename','state','error'),'display_status'=>UploadStatusPresenter::label($file->state)])];});$exports=MediaExport::where('group_id',$group->id)->where('user_id',$r->user()->id)->latest()->limit(20)->get();return Inertia::render('Groups/Operations',['group'=>$group->only('id','name'),'folders'=>$group->folders()->withCount('photos')->get(['id','group_id','name']),'batches'=>$batches,'exports'=>$exports,'indexRun'=>EventFaceIndexRun::where('group_id',$group->id)->latest()->first()]);}
    public function reviews(Request$r,Group$group){Gate::authorize('manageMembers',$group);$reviews=FaceMatchResult::whereHas('asset',fn($q)=>$q->where('group_id',$group->id))->where('review_state','unreviewed')->with(['asset.photo','faceSearchSubject'])->latest()->get()->filter(fn($m)=>$m->asset?->state==='completed')->map(fn($m)=>['id'=>$m->id,'similarity'=>(float)$m->similarity,'photo_url'=>route('media.show',[$m->asset->uuid,'thumbnail']),'subject_uuid'=>$m->faceSearchSubject->uuid]);return Inertia::render('Groups/Reviews',['group'=>$group->only('id','name'),'reviews'=>$reviews]);}
    public function edit(Request$r,Group$group){return $this->renderSettings($group,'general');}
