    private function renderSettings(Group$group,string$section){Gate::authorize('update',$group);$group->load('coverMediaAsset.variants','pendingCoverMediaAsset.variants');return Inertia::render('Groups/Settings',['group'=>$group->only('id','name','description','event_type','event_date','location','privacy','is_active','membership_status','membership_limit','anyone_with_link_can_join','anonymous_access_mode','downloads_enabled','favourites_enabled','participants_can_edit_identity','allow_guest_upload','face_recognition_enabled','watermark_enabled','watermark_text','invitation_expires_at','event_code_expires_at'),'cover'=>$this->coverPresenter->present($group,'cover_large'),'section'=>$section,'counts'=>['participants'=>$group->members()->count(),'folders'=>$group->folders()->count(),'favorites'=>$group->photos()->whereHas('likes')->count()]]);}
    public function members(Request$r,Group$group){Gate::authorize('manageMembers',$group);$members=$group->members()->get()->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'role'=>$u->pivot->role,'access_type'=>$u->pivot->access_type,'status'=>$u->pivot->membership_status]);return Inertia::render('Groups/Members',['group'=>$group->only('id','name'),'members'=>$members,'invites'=>$group->accessInvites()->get()->map(fn($i)=>['id'=>$i->id,'label'=>$i->label,'code'=>$i->access_code,'active'=>$i->isUsable(),'expires_at'=>$i->expires_at])]);}
    public function favorites(Request$r,Group$group){Gate::authorize('update',$group);abort_unless($group->favourites_enabled,403);$photos=$group->photos()->whereHas('likes')->withCount('likes')->with('mediaAsset')->get()->filter(fn($p)=>$p->mediaAsset?->state==='completed'&&Gate::forUser($r->user())->allows('view',$p))->map(fn($p)=>['id'=>$p->id,'filename'=>$p->original_filename,'favorites_count'=>$p->likes_count,'url'=>route('media.show',[$p->mediaAsset->uuid,'thumbnail'])])->values();return Inertia::render('Groups/Favorites',['group'=>$group->only('id','name'),'photos'=>$photos]);}
